let size = 8
let values = []
let seed = 42
for (let i in 0 to size) {
 seed = (seed * 1103515245 + 12345) % 2147483648
 let value = seed % 2000001 - 1000000

 values.append(value)
}

let started = clock_ns()
var checksum = 0
for (let repetition in 0 to 2048) {
 let queue = copy(values)
 sort(queue)
 for (let i in 0 to len(queue)) {
  let item = queue[i]
  checksum = checksum + (item) * (i % 7 + 1)
 }
}
print(checksum)
print(clock_ns() - started)

